// APEX Tune Live — licensed real-human articulation preservation audit.
//
// This is a descriptive audio-quality fingerprint, NOT a listening-quality
// certification. In particular, high-frequency-rich != verified /s/ syllable.
// It compares voice dynamics and >3.5 kHz high-pass fraction of the exact
// source, shipping HQ40 and NONSHIPPING compensated research at 40ms PDC.
//
// The input is public CC BY 4.0 Vocadito, never the artist's private audio.
// Only reads files generated by the voice workflow; never changes the DAW.
#define main offline_audition_main_not_called
#include "tune_live_offline_audition.cpp"
#undef main
#include <algorithm>
#include <array>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {
constexpr int frame=1024;
constexpr double pi=3.1415926535897932384626433832795;
constexpr double floorPower=1.e-12;
struct EnergyFrame {double all=0,high=0;};
struct Metrics {
    std::vector<double> levels,highRichLoss,highFractionChange;
    int active=0,highRich=0;
    double peak=0;
};
double median(std::vector<double> values) {
    if(values.empty())return std::numeric_limits<double>::quiet_NaN();
    const auto n=values.size()/2;
    std::nth_element(values.begin(),values.begin()+static_cast<std::ptrdiff_t>(n),values.end());
    return values[n];
}
std::vector<EnergyFrame> bands(const Wave& source,std::size_t frameOffset,
                               std::size_t count) {
    const double decay=std::exp(-2.0*pi*3500.0/source.rate);
    double lpf=0;
    std::vector<EnergyFrame> output;
    output.reserve(count);
    const auto stride=static_cast<std::size_t>(source.channels);
    for(std::size_t j=0;j<count;++j) {
        EnergyFrame energy;
        for(int i=0;i<frame;++i) {
            const std::size_t n=frameOffset+j*frame+
                                static_cast<std::size_t>(i);
            const double sample=source.data[n*stride];
            if(!std::isfinite(sample))
                throw std::runtime_error("nonfinite input sample");
            lpf=decay*lpf+(1.0-decay)*sample;
            const double hp=sample-lpf;
            energy.all+=sample*sample;
            energy.high+=hp*hp;
        }
        energy.all/=frame;
        energy.high/=frame;
        output.push_back(energy);
    }
    return output;
}
Metrics evaluate(const Wave& source,const Wave& candidate,
                 const std::vector<EnergyFrame>& sourceEnergy,
                 std::size_t first, std::size_t count,int pdc) {
    Metrics m;
    // The research and approved HQ40 versions have EXACTLY the same 40ms PDC.
    const auto wet= bands(candidate, first+static_cast<std::size_t>(pdc)/frame,
                            count+1);
    // But PDC is not necessarily frame-aligned: avoid a 1764/1024 rounding
    // error by measuring wet at the actual exact sample offset below.
    // Recompute wet with exact 1764 sample shift across output WAV. 1024
    // nonoverlapping source windows, no resampling or estimate of timing.
    const auto samplesPerFrame=static_cast<std::size_t>(frame);
    const auto stride=static_cast<std::size_t>(source.channels);
    const double decay=std::exp(-2.0*pi*3500.0/source.rate);
    double lpf=0.0;
    (void)wet;
    for(std::size_t j=0;j<count;++j) {
        const auto& dry=sourceEnergy[j];
        const auto firstSample=(first+j)*samplesPerFrame+
                               static_cast<std::size_t>(pdc);
        double total=0.0,high=0.0;
        for(int i=0;i<frame;++i) {
            const double sample=candidate.data[(firstSample+
                    static_cast<std::size_t>(i))*stride];
            if(!std::isfinite(sample))
                throw std::runtime_error("nonfinite candidate");
            m.peak=std::max(m.peak,std::abs(sample));
            lpf=decay*lpf+(1.0-decay)*sample;
            const double hp=sample-lpf;
            total+=sample*sample;
            high+=hp*hp;
        }
        total/=frame;high/=frame;
        if(dry.all<1.e-6)continue; // below -60dBFS RMS: not meaningful
        ++m.active;
        const double db=10.0*std::log10((total+floorPower)/
                                            (dry.all+floorPower));
        const double relativeHF=10.0*std::log10(
             ((high+floorPower)/(total+floorPower))/
             ((dry.high+floorPower)/(dry.all+floorPower)));
        m.levels.push_back(db);
        m.highFractionChange.push_back(relativeHF);
        // Strong high-frequency fraction and non-silent signal are only
        // an *acoustic proxy* for consonants, hiss and breathy syllables.
        if(dry.high/dry.all > 0.12) {
            ++m.highRich;
            m.highRichLoss.push_back(10.0*std::log10(
                (high+floorPower)/(dry.high+floorPower)));
        }
    }
    return m;
}
void report(std::ostream& out,const char* label,const Metrics& m) {
    out<<label
       <<" active_frames="<<m.active
       <<" HF_rich_source_frames="<<m.highRich
       <<" median_total_level_change_db="<<median(m.levels)
       <<" median_HF_fraction_change_db="<<median(m.highFractionChange)
       <<" median_HF_rich_band_level_change_db="<<median(m.highRichLoss)
       <<" maximum_window_sample_peak="<<m.peak<<"\\n";
}
}
int main(int argc,char** argv) {
    try {
        if(argc!=3 || std::string(argv[1])!="--prefix")
            throw std::runtime_error("Usage: --prefix vocadito_human|vocadito_low|vocadito_high");
        const std::string prefix=argv[2];
        const auto source=readWave(prefix+"_source.wav");
        const auto baseline=readWave(prefix+"_hq40.wav");
        const auto candidate=readWave(prefix+"_research_compensated.wav");
        if(source.rate!=baseline.rate||source.rate!=candidate.rate||
           source.channels!=baseline.channels||
           source.channels!=candidate.channels||
           source.frames()!=baseline.frames()||
           source.frames()!=candidate.frames())
            throw std::runtime_error("Audio formats or lengths differ");
        const int pdc=static_cast<int>(std::lround(source.rate*0.04));
        const std::size_t first=static_cast<std::size_t>(source.rate)/frame;
        const std::size_t sampleStart=first*frame;
        if(source.frames()<sampleStart+frame*120+
                               static_cast<std::size_t>(pdc))
            throw std::runtime_error("Insufficient sustained human singing for analysis");
        const std::size_t count=(source.frames()-static_cast<std::size_t>(pdc)
                                  -sampleStart)/frame;
        const auto orig=bands(source,sampleStart, count);
        // bands() accepts sample index as the offset, not frame index.
        // Report against precise 40ms sample-aligned dry and wet windows.
        const auto hq=evaluate(source,baseline,orig,first,count,pdc);
        const auto experimental=evaluate(source,candidate,orig,first,count,pdc);
        std::ostringstream out;
        out<<std::fixed<<std::setprecision(4)
           <<"APEX HUMAN PHONETIC-TRANSIENT / SPECTRAL FINGERPRINT"
           <<" profile="<<prefix
           <<" sr="<<source.rate
           <<" channels="<<source.channels
           <<" pdc_samples="<<pdc
           <<" measured_frames="<<count
           <<" window_samples="<<frame<<"\\n";
        report(out,"SINGER_APPROVED_HQ40",hq);
        report(out,"EXPERIMENTAL_DOWNSHIFT",experimental);
        out<<"CAVEAT: 3.5kHz one-pole highpass ratio is NOT phoneme "
              "recognition, naturalness, true formant EQ or a listening ABX test.\\n";
        if(hq.active<100 || experimental.active<100 ||
           hq.highRich<5 || experimental.highRich<5 ||
           !std::isfinite(median(hq.highRichLoss)) ||
           !std::isfinite(median(experimental.highRichLoss)) ||
           hq.peak<=0 || experimental.peak<=0 ||
           hq.peak>=1 || experimental.peak>=1)
            throw std::runtime_error("Not enough valid, finite real vocal spectral evidence");
        const std::string reportPath=prefix+"_ARTICULATION_SPECTRAL_REPORT.txt";
        std::ofstream file(reportPath);
        if(!file)throw std::runtime_error("Cannot create report");
        file<<out.str();
        std::cout<<out.str();
        std::cout<<"APEX_HUMAN_ARTICULATION_AUDIT_PASS prefix="<<prefix<<"\\n";
        return 0;
    } catch(const std::exception& ex) {
        std::cerr<<"APEX_HUMAN_ARTICULATION_AUDIT_FAIL "<<ex.what()<<"\\n";
        return 1;
    }
}
